from deepdiff import DeepDiff, model
import string
from robot.api import logger
import re

CHANGES = 0


class CommandComparer(object):
    def __init__(self, admin_command_name, admin_command_pattern, admin_command_current):
        self.command_name = admin_command_name
        self.command_pattern = admin_command_pattern
        self.command_current = admin_command_current
        if type(self.command_pattern) == type(self.command_current):
            self.comparison = DeepDiff(self.command_pattern, self.command_current, ignore_order=True)
        else:
            logger.error('Cannot compare two different variable types. {var1type} != {var2type}'.format(
                var1type=type(self.command_pattern), command_resp_2type=type(self.command_current)))
        logger.info('command_name: {}'.format(self.command_name))
        logger.info('comparison.keys : {}'.format(self.comparison.keys()))
        logger.info('comparison: {}'.format(self.comparison))

    def compare_commands_result(self):
        self.compare_diff(diff=self.comparison)
        logger.error('number of changes {}'.format(self.get_number_of_changes()))

    def compare_diff(self, diff, dict_prefix=False):
        logger.info('diff: {}'.format(diff))
        for comparison_key in diff.keys():
            if comparison_key == 'values_changed':
                for dict_param, dict_values in diff['values_changed'].items():
                    self.compare_changed(dict_param, dict_values['old_value'], dict_values['new_value'], dict_prefix)
            elif comparison_key == 'iterable_item_added':
                self.log_add_remove(diff=diff, oper_type='iterable_item_added', place_of_change_prefix=dict_prefix)
            elif comparison_key == 'iterable_item_removed':
                self.log_add_remove(diff=diff, oper_type='iterable_item_removed', place_of_change_prefix=dict_prefix)
            elif comparison_key == 'dictionary_item_removed':
                self.log_add_remove(diff=diff, oper_type='dictionary_item_removed', place_of_change_prefix=dict_prefix)
            elif comparison_key == 'dictionary_item_added':
                self.log_add_remove(diff=diff, oper_type='dictionary_item_added', place_of_change_prefix=dict_prefix)
            else:
                logger.error('Not know structure type in command output.\nstructure: {}'.format(comparison_key))

    def log_add_remove(self, diff, oper_type, place_of_change_prefix=False):
        global CHANGES
        if isinstance(diff[oper_type], model.PrettyOrderedSet):
            for elem in diff[oper_type]:
                readable_dict_name = self.get_readable_dict_path(elem)
                readable_dict_prefix = self.get_readable_dict_path(place_of_change_prefix)
                dict_name = self.merge_paths(readable_dict_name, readable_dict_prefix)
                oper_name = re.split('_', oper_type)[-1]
                command = self.command_pattern if oper_name == 'removed' else self.command_current
                logger.error('{}: {}\n{}: {}'.format(self.command_name,
                                                     oper_name,
                                                     dict_name,
                                                     self.get_value_added_or_remove_item(command,
                                                                                         dict_name)))
        elif isinstance(diff[oper_type], dict):
            for dict_item, value_item in diff[oper_type].items():
                readable_dict_name = self.get_readable_dict_path(dict_item)
                readable_dict_prefix = self.get_readable_dict_path(place_of_change_prefix)
                dict_name = self.merge_paths(readable_dict_name, readable_dict_prefix)
                logger.error('{}: {}\n{}: {}'.format(self.command_name,
                                                     re.split('_', oper_type)[-1],
                                                     dict_name,
                                                     value_item))
        else:
            logger.error('Who knows what it is.')
        CHANGES += 1

    @staticmethod
    def get_value_added_or_remove_item(comm_output, place_of_change):
        place_of_change_list = re.split(r'->', place_of_change)
        for i in range(len(place_of_change_list)):
            place = int(place_of_change_list[i]) if re.search(r'^\d{1,2}$', place_of_change_list[i]) else \
                place_of_change_list[i]
            comm_output = comm_output[place]
            if i == len(place_of_change_list) - 1:
                return comm_output

    def log_changes(self, dict_name, pattern, current):
        global CHANGES
        place_of_change = self.get_readable_dict_path(str(dict_name))
        logger.error('{name}: value in {change} was changed\nfrom: {p}\nto:   {c}'.format(name=self.command_name,
                                                                                           change=place_of_change,
                                                                                           p=pattern,
                                                                                           c=current))
        CHANGES += 1

    @staticmethod
    def get_number_of_changes():
        return CHANGES

    def compare_str(self, dict_name, pattern_str, current_str):
        pattern_special_chars = sum(char in string.punctuation for char in pattern_str)
        current_special_chars = sum(char in string.punctuation for char in current_str)
        if pattern_special_chars != current_special_chars or len(pattern_str) != len(current_str):
            self.log_changes(dict_name, pattern_str, current_str)

    def compare_num(self, dict_name, pattern_num, current_num):
        str_pattern_num, str_current_num = str(pattern_num), str(current_num)
        if len(str_pattern_num) != len(str_current_num):
            self.log_changes(dict_name, pattern_num, current_num)

    def compare_list(self, dict_name, pattern_list, current_list):
        diff_list = DeepDiff(pattern_list, current_list, ignore_order=True)
        self.compare_diff(diff=diff_list, dict_prefix=dict_name)

    def compare_dict(self, dict_name, pattern_dict, current_dict):
        diff_dict = DeepDiff(pattern_dict, current_dict, ignore_order=True)
        self.compare_diff(diff=diff_dict, dict_prefix=dict_name)

    def compare_bool(self, dict_name, pattern_bool, current_bool):
        if not pattern_bool == current_bool:
            self.log_changes(dict_name, pattern_bool, current_bool)

    def compare_changed(self, dict_name, pattern_var, current_var, dict_prefix=False):
        readable_dict_name = self.get_readable_dict_path(dict_name)
        readable_dict_prefix = self.get_readable_dict_path(dict_prefix)
        dict_name = self.merge_paths(readable_dict_name, readable_dict_prefix)

        if isinstance(pattern_var, str):
            self.compare_str(dict_name, pattern_var, current_var)

        elif isinstance(pattern_var, int) or isinstance(pattern_var, float):
            self.compare_num(dict_name, pattern_var, current_var)

        elif isinstance(pattern_var, list):
            self.compare_list(dict_name, pattern_var, current_var)

        elif isinstance(pattern_var, dict):
            self.compare_dict(dict_name, pattern_var, current_var)
        else:
            print("don't know the type pattern: {}, current {}".format(type(pattern_var), type(current_var)))

    @staticmethod
    def get_readable_dict_path(path):
        return re.sub(r'\[', '->', re.sub(r'\]|\'|root\[', '', path)) if path else False
        # return re.sub(r'\]|\'', '', re.sub(r'\[', '->', str(path)))

    @staticmethod
    def merge_paths(path, prefix):
        return prefix + '->' + path if prefix else path
